"""Snapping span times to a fixed payroll step."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour: {step}"
        )


def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, halfway rounds up."""
    return (minute + step // 2) // step * step


def _label(span: Span) -> str:
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"


# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both ends; ValueError if the span collapses."""
    _check_step(step)
    return Span(
        _snap(span.start, step),
        _snap(span.end, step),
    )


# ---
def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    _check_step(step)
    snapped = [round_span(item, step) for item in spans]
    return [_label(item) for item in snapped]

