# owner: platform
import unittest

from hourglass.rounding import round_span, round_spans
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        result = round_span(Span(543, 1032), 15)
        self.assertEqual(result, Span(540, 1035))

    def test_halfway_rounds_up(self):
        result = round_span(Span(7, 38), 15)
        self.assertEqual(result, Span(0, 45))

    def test_end_of_day_stays(self):
        result = round_span(Span(1400, 1440), 30)
        self.assertEqual(result, Span(1410, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 544), 15)


class RoundSpansTests(unittest.TestCase):
    def test_label(self):
        labels = round_spans([Span(543, 1032)], 15)
        self.assertEqual(
            labels, ["09:00-17:15 (8h 15m)"]
        )

    def test_whole_hours(self):
        labels = round_spans([Span(540, 600)], 60)
        self.assertEqual(
            labels, ["09:00-10:00 (1h 0m)"]
        )

    def test_many_and_empty(self):
        spans = [Span(0, 60), Span(61, 118)]
        labels = round_spans(spans, 1)
        self.assertEqual(len(labels), 2)
        self.assertEqual(round_spans([], 5), [])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)

    def test_bad_step_raises_when_empty(self):
        with self.assertRaises(ValueError):
            round_spans([], 0)
